import json
import logging
import re
import time

from taf.internal.protocol.tl1 import TL1, TL1SSHShellSession

from taf.hw.optical_switch.attributes import (
    OptionalBoolAttributeFactory,
    OptionalStrAttributeFactory,
    OptionalStrEnumAttributeFactory,
    RequiredStrAttributeFactory,
)
from taf.hw.optical_switch.devices.base import OpticalSwitch
from taf.hw.optical_switch.devices.http import HttpOpticalSwitch
from taf.hw.optical_switch.exceptions import (
    InvalidInput,
    OpticalSwitchCommandInvalid,
    OpticalSwitchResponseError,
    Timeout,
)


class CalientS320:
    def __new__(cls, addr, **kwargs):
        protocol = kwargs.pop("protocol", "http")

        if protocol == "tl1":
            return CalientS320Tl1(addr, **kwargs)
        elif protocol in ["http", "https"]:
            return CalientS320Http(addr, protocol=protocol, **kwargs)
        else:
            raise ValueError(f"Non-supported protocol: {protocol}")


class CalientSettings:
    """
    {
      "in": "1.1.1/1",
      "out": "1.1.1/1",
      "group": "<groupname>/SYSTEM",
      "conn": "<connname>",
      "dir": "uni/bi",
      "band": "C/O/L/S/W",
      "nolight": "true/false",
      "deadreckon": "true/false"
    }
    """

    def __init__(self, platformtype="3D"):
        _port_pattern = r"^\d*$" if platformtype == "1D" else r"\d\.\d\.\d"
        self._attribute_factories = {
            "in_port": RequiredStrAttributeFactory(attribute_name="in", pattern=_port_pattern),
            "out_port": RequiredStrAttributeFactory(attribute_name="out", pattern=_port_pattern),
            "group": OptionalStrAttributeFactory(attribute_name="group", default_value="SYSTEM"),
            "conn": OptionalStrAttributeFactory(attribute_name="conn"),
            "dir": OptionalStrEnumAttributeFactory(attribute_name="dir", default_value="bi", candidates=["uni", "bi"]),
            "band": OptionalStrEnumAttributeFactory(
                attribute_name="band",
                default_value="C",
                candidates=["C", "O", "L", "S", "W"],
            ),
            "nolight": OptionalBoolAttributeFactory(attribute_name="nolight", default_value=False, repr="str"),
            "deadreckon": OptionalBoolAttributeFactory(attribute_name="deadreckon", default_value=False, repr="str"),
        }

        self._reset_attributes()

    def _reset_attributes(self):
        self._attributes = []
        for key in self._attribute_factories:
            setattr(self, key, None)

    def load(self, new_settings):
        self._reset_attributes()
        for key, value in new_settings.items():
            lower_key = key.lower()
            for atrr_name, attribute_factory in self._attribute_factories.items():
                if lower_key == attribute_factory.attribute_name:
                    attribute = attribute_factory.create(value)
                    setattr(self, atrr_name, attribute)
                    self._attributes.append(attribute)

        if not self.in_port or not self.out_port:
            raise InvalidInput("in or out attribute was not set")

    def dumps(self):
        return json.dumps(dict([attribute.to_tuple() for attribute in self._attributes]))


class CalientS320Http(HttpOpticalSwitch):
    """
    | Represents CalientS320 using HTTP protocol
    | Kwargs available in the interface:

    :param str model: name of the optical switch model
    :param str addr: IP address or hostname of the device
    :param int, optional timeout: timeout for the request in seconds *(defaults to 5)*
    :param str, optional user_name: username for authentication *(defaults to empty string)*
    :param str, optional password: password for authentication *(defaults to empty string)*
    :param int, optional port: port number of the device *(defaults to 80)*
    :param str, optional protocol: See note at the top of the page
    """

    # Class using rest api to operate Calient S320.
    # parameter in setting: dict, it defines the ports of the connection,
    # where key is 'from' port and value is 'to' port, eg:{'1.1.1': '4.1.2', '1.2.1': '1.2.6'}
    # CalienS320 has two (or more) platform types which depends on port representation:
    # '1D' = e.g. '33-117' or '33>117'
    # '3D' = e.g. '1.1.1-4.1.2' or '1.1.1>4.1.2' or '1.1.1<4.1.2'
    # NOTE: not known if pattern for '3D' is adequate only for those type or others e.g. 2D, 4D

    _CROSS_CONNECTIONS_LIST_URL = "/rest/crossconnects/?id=list"
    _CROSS_CONNECTIONS_DELETE_ALL_URL = "/rest/crossconnects/?id=deleteall"
    _CROSS_CONNECTIONS_DELETE_ANY_URL = "/rest/crossconnects/?id=delete&conn={conn}"
    _CROSS_CONNECTIONS_DETAILS_URL = "/rest/crossconnects/?id=detail&conn={conn}"
    _CROSS_CONNECTIONS_ACTIVATE_URL = "/rest/crossconnects/?id=activate&conn={conn}"
    _CROSS_CONNECTIONS_DEACTIVATE_URL = "/rest/crossconnects/?id=deactivate&conn={conn}"
    _CROSS_CONNECTIONS_BULK_ADD_URL = "/rest/crossconnects/?id=badd"
    _CROSS_CONNECTIONS_BULK_DELETE_URL = "/rest/crossconnects/?id=bdel"
    _CROSS_CONNECTIONS_ADD_URL = "/rest/crossconnects/?id=add"

    _PORT_LIST_URL = "/rest/ports/?id=summary"
    _PORT_INFO = "/rest/ports/?id=info"
    _PORT_DROPOUT = "/rest/ports/?id=dropout"

    _MINIMUM_RETRY_TIME = 5
    _SLEEP_INTERVAL = 0.5

    def __init__(self, addr, port=80, protocol="http", user_name="", password="", timeout=5):
        super().__init__(
            addr=addr,
            port=port,
            protocol=protocol,
            user_name=user_name,
            password=password,
            timeout=timeout,
        )
        self.platform_type = self._get_platform_type()

    def get_optical_switch_channels(self):
        """
        Get information about optical switch channels

        :return: dictionary with input port as key and output port as value
        :raises OpticalSwitchConnectionError: HTTP connection error occurred
        :raises OpticalSwitchResponseError: Response status is not 200
        """
        relative_url = self._build_http_get_optical_switch_channels_relative_url()
        response = self.http_client.get(relative_url=relative_url)
        parsed_response = self._parse_get_channels_response(response)
        return parsed_response

    def set_optical_switch_channels(self, new_settings):
        """
        Set optical switch channels settings

        :param dict new_settings: dictionary with input port as key and output port as value.
            For example: ``{'1.1.1': '2.2.2'}`` - '1.1.1' is from_id, '2.2.2' is to_id.

        :raises Timeout(OpticalSwitchConnectionError): Request didn't succeed in the specified timeout,
            timeout is set during class initialization, if it is less than 5 seconds, then it will be set to 5 seconds.
        :raises OpticalSwitchConnectionError: HTTP connection error occurred
        :raises OpticalSwitchResponseError: Response status is not 200
        :raises InvalidInput(OpticalSwitchError): Input is not a dictionary or ports are out of range
        """
        self._validate_settings(new_settings)
        self._set_optical_switch_channels(new_settings)
        self._check_if_settings_changed(new_settings)

    def remove_connections(self, in_ports=None, out_ports=None, **kwargs):
        """
        Remove specified connections

        **In case of bidirectional connections**:

            Close all connection that contain any port given in ``in_ports`` **OR** ``out_ports``

            For example, if there is a bidirectional connection: *"1.1.1-2.2.2"*, all of this calls would correctly
            close this connection, because in this type of connection both ports are treated as both
            input and output port:

            ``optical_switch.remove_connections(in_ports=['1.1.1'])``,
            ``optical_switch.remove_connections(in_ports=['2.2.2'])``,
            ``optical_switch.remove_connections(out_ports=['1.1.1'])``,
            ``optical_switch.remove_connections(out_ports=['2.2.2'])``,
            ``optical_switch.remove_connections(in_ports=['1.1.1'], out_ports=['2.2.2'])``

        **In case of unidirectional connections**:

            Close all connection that contain:

            * port given in ``in_ports`` on the left side of the connection
            * port given in ``out_ports`` on the right side of the connection

            For example, if there are connections "1.1.1>2.2.2", "1.1.1>4.2.1":

            | ``optical_switch.remove_connections(in_ports=['1.1.1'])`` will close both connections
            | ``optical_switch.remove_connections(out_ports=['2.2.2'])`` will close only "1.1.1>2.2.2"
            | ``optical_switch.remove_connections(out_ports=['4.2.1'])`` will close only "1.1.1>4.2.1"

        :param list[str] in_ports: list of input ports to be closed
        :param list[str] out_ports: list of output ports to be closed
        :raises OpticalSwitchConnectionError: HTTP connection error occurred
        :raises OpticalSwitchResponseError(OpticalSwitchError): Response status is not 200

        """

        if not in_ports and not out_ports:
            logging.debug("No ports were specified")
            return

        path = self._build_http_get_optical_switch_channels_relative_url()
        response = self.http_client.get(relative_url=path)
        channels = self._parse_get_channels_response(response, output_formatter=self._parse_channels_to_tuples)
        cnnids = self._filter_connections_by_ports(channels, in_ports=in_ports, out_ports=out_ports)
        logging.info(f"Connections `{cnnids}` will be removed")
        self._bulk_delete_connections(cnnids)

    def set_optical_switch_channel(self, new_settings):
        """
        Sets a single optical switch channel settings

        :param dict new_settings: dictionary with new channel settings.
            For Example::

                {
                    'in': '1.1.1',   # required str, fromid
                    'out':'2.2.2',   # required str, toid
                    'group': 'SYSTEM', # optional str, group name, 'SYSTEM' by default
                    'conn': '1.1.1-2.2.2', # optional str, connection name, in-out formatted by default
                    'dir': 'bi', # optional str, direction, [bi|uni], 'bi' by default
                    'band': 'C', # optional str, band, [C|O|L|S|W], 'C' by default
                    'nolight': False, #optional str or bool, case insensitive, False by default
                    'deadreckon': False  #optional str or bool, case insensitive, False by default
                }

        :raises OpticalSwitchConnectionError: HTTP connection error occurred
        :raises OpticalSwitchResponseError(OpticalSwitchError): Response status is not 200
        :raises Timeout(OpticalSwitchConnectionError): Request didn't succeed in the specified timeout,
        :raises InvalidInput(OpticalSwitchError): Provided settings were incorrect

        """
        settings_obj = CalientSettings(platformtype=self.platform_type)
        settings_obj.load(new_settings)
        response = self.http_client.post(relative_url=self._CROSS_CONNECTIONS_ADD_URL, data=settings_obj.dumps())
        self._check_response_status_code_equal_200(response)
        self._verify_response_status(response, errmsg="Failed to set connection ")

        in_out = {settings_obj.in_port.value: settings_obj.out_port.value}
        self._check_if_settings_changed(in_out)

    def activate_connection(self, connection):
        """
        Activate specified connection

        :param str connection: connection identity.
            Example for bidirectional conn.: ``"1.1.1-4.1.2"``.
            Example for unidirectional conn.: ``"1.1.1>4.1.2"``
        :raises OpticalSwitchConnectionError: HTTP connection error occurred
        :raises OpticalSwitchResponseError: Response status is not 200
        """
        response = self.http_client.post(relative_url=self._CROSS_CONNECTIONS_ACTIVATE_URL.format(conn=connection))
        self._check_response_status_code_equal_200(response)
        self._verify_response_status(response, errmsg=f"Failed to activate connection '{connection}'")

    def deactivate_connection(self, connection):
        """
        Activate specified connection

        :param str connection: connection identity.
            Example for bidirectional conn.: ``"1.1.1-4.1.2"``.
            Example for unidirectional conn.: ``"1.1.1>4.1.2"``

        :raises OpticalSwitchConnectionError: HTTP connection error occurred
        :raises OpticalSwitchResponseError: Response status is not 200

        """
        response = self.http_client.post(relative_url=self._CROSS_CONNECTIONS_DEACTIVATE_URL.format(conn=connection))
        self._check_response_status_code_equal_200(response)
        self._verify_response_status(response, errmsg=f"Failed to deactivate connection '{connection}'")

    def get_optical_switch_connection_details(self, connection):
        """
        Get optical switch connection details.

        :param str connection: connection identity.
            Example for bidirectional conn.: ``"1.1.1-4.1.2"``.
            Example for unidirectional conn.: ``"1.1.1>4.1.2"``
        :return: dictionary with connection details
        :raises OpticalSwitchConnectionError: HTTP connection error occurred
        :raises OpticalswitchResponseError: Response status is not 200
        :raises InvalidInput(OpticalSwitchError): Given connection does not exist

        """
        relative_url = self._build_http_get_optical_switch_connection_details_relative_url(connection)
        response = self.http_client.get(relative_url=relative_url)
        parsed_response = self._parse_get_connection_details_response(response)
        return parsed_response

    def dropout(self, port, duration):
        """
        Trigger a single short power outage, down to 1ms, on the specified port.
        The port parameter must be the output port of an existing cross connection.

        :param str port: output port. Example: ``"1.1.1"``
        :param str duration: dropout duration in milliseconds. Example: ``"30"``
        :raises OpticalSwitchConnectionError: HTTP connection error occurred
        :raises OpticalSwitchResponseError: Response status is not 200
        """
        response = self.http_client.post(
            relative_url=self._PORT_DROPOUT,
            data=json.dumps({"port": port, "duration_milliseconds": duration}),
        )
        self._check_response_status_code_equal_200(response)
        self._verify_response_status(response, errmsg=f"Failed to set dropout on port '{port}'")

    def _get_platform_type(self):
        return self.http_client.get(self._PORT_INFO).json()[0]["info"]["platformtype"]

    def _build_http_get_optical_switch_channels_relative_url(self):
        return self._CROSS_CONNECTIONS_LIST_URL

    def _build_http_get_optical_switch_connection_details_relative_url(self, connection):
        return self._CROSS_CONNECTIONS_DETAILS_URL.format(conn=connection)

    def _parse_get_channels_response(self, response, output_formatter=None):
        status_code = response.status_code
        if status_code == 204:
            logging.warning("No channel in use")
            return []

        self._check_response_status_code_equal_200(response)
        formatter = output_formatter or self._parse_channels_to_dict
        connection_dict = formatter(response.json())
        return connection_dict

    def _parse_channels_to_dict(self, channels):
        result = {}
        for channel in channels:
            from_id, _, to_id = self._parse_connid(channel["connid"])
            result[from_id] = to_id

        return result

    def _parse_get_connection_details_response(self, response):
        status_code = response.status_code
        if status_code == 204:
            raise InvalidInput("Connection id does not exist")

        self._check_response_status_code_equal_200(response)
        return response.json()[0]

    def _validate_settings(self, settings):
        super()._validate_settings(settings)
        self._check_if_ports_in_range(settings)

    def _check_if_ports_in_range(self, settings):
        setting_ports = []
        for from_id, to_id in settings.items():
            setting_ports.extend([from_id, to_id])
        all_ports = self._get_all_ports()
        out_range_ports = set(setting_ports).difference(set(all_ports))
        if out_range_ports:
            raise InvalidInput(f"Port(s) {out_range_ports} out of range")

    def _get_all_ports(self):
        response = self.http_client.get(relative_url=self._PORT_LIST_URL)

        self._check_response_status_code_equal_200(response)

        ports_list = []
        for element in response.json():
            ports_list.append(element["port"])
        logging.debug(f"All ports:{ports_list}")
        return ports_list

    def _parse_connid(self, connid):
        """
        :param: str, '1.1.1-4.1.2' or '1.1.1>4.1.2' or '1.1.1<4.1.2' or '33-117' or '33>117'
        :return: tuple, e.g. ('1.1.1', '-', '4.1.2') or ('033', '-', '117')
        """
        regex = r"(\d+)([<>-])(\d+)" if self.platform_type == "1D" else r"((?:\d+\.){2}\d+)([->])((?:\d+\.){2}\d+)"
        pattern = re.compile(regex)
        return pattern.findall(connid)[0]

    def _set_optical_switch_channels(self, settings):
        """
        Send given channel settings.
        If setting fail due to another request being processed, retry until timeout.
        """
        logging.warning("Enforce exist connection closing if conflict!")
        start = time.time()
        timeout = max(self._MINIMUM_RETRY_TIME, self._timeout)
        while time.time() - start < timeout:
            if self._set_bulk_provision(settings):
                return
            logging.info("Command rejected because another request is being processed, resending request.")
            time.sleep(self._SLEEP_INTERVAL)
        raise Timeout(f"Request didn't succeed in {timeout}s")

    def _set_bulk_provision(self, settings):
        """
        Bulk Provision one or more cross connects.
        """
        bulk_conn = []
        for from_id, to_id in settings.items():
            bulk_conn.append({"in": from_id, "out": to_id, "dir": "bi"})
        response = self.http_client.post(
            relative_url=self._CROSS_CONNECTIONS_BULK_ADD_URL,
            data=json.dumps(bulk_conn),
        )

        self._check_response_status_code_equal_200(response)

        for element in response.json():
            if element["response"]["status"] == "0":
                logging.debug(
                    "Set Connection {}-{} failed. {}".format(
                        element["in"],
                        element["out"],
                        element["response"]["description"],
                    )
                )
                return False

        return True

    def _check_if_settings_changed(self, settings):
        """
        Wait until changes came into effect.
        """
        start = time.time()
        timeout = max(self._timeout, len(settings) * self._MINIMUM_RETRY_TIME)
        while time.time() - start < timeout:
            if set(settings.items()).issubset(self.get_optical_switch_channels().items()):
                logging.debug(f"Successfully set optical switch channel(s) {settings}.")
                return
            time.sleep(self._SLEEP_INTERVAL)
        raise Timeout(f"Set optical switch channel(s) {settings} unsuccessful in {timeout}s.")

    def _parse_channels_to_tuples(self, channels):
        return [self._parse_connid(channel["connid"]) for channel in channels]

    def _filter_connections_by_ports(self, connections, in_ports=None, out_ports=None):
        cnnids = set()
        in_port_set = set(in_ports) if in_ports else set()
        out_port_set = set(out_ports) if out_ports else set()
        ports = in_port_set.union(out_port_set)

        for left_id, direction, right_id in connections:
            cnnid = None
            original_cnnid = f"{left_id}{direction}{right_id}"
            if direction == "-":  # connection is bidirectional
                if left_id in ports or right_id in ports:
                    cnnid = original_cnnid

            elif direction == ">":  # connection is unidirectional
                if left_id in in_port_set or right_id in out_port_set:
                    cnnid = f"{left_id}{direction}{right_id}"
            else:
                logging.debug(f"Invalid direction {direction}")

            cnnids.add(cnnid) if cnnid else None
        return cnnids

    def _bulk_delete_connections(self, cnnids):
        data = [{"conn": cnnid} for cnnid in cnnids]
        response = self.http_client.post(relative_url=self._CROSS_CONNECTIONS_BULK_DELETE_URL, data=json.dumps(data))
        status_code = response.status_code
        if status_code == 204:
            logging.warning("No channel in use")
            return []

        self._check_response_status_code_equal_200(response)

    def _verify_response_status(self, response, errmsg=""):
        for element in response.json():
            if element["status"] == "0":
                raise OpticalSwitchResponseError(f"{errmsg} {element['description']}")

    def teardown(self):
        """Close connection with the device"""
        super().teardown()


class CalientS320Tl1(OpticalSwitch):
    """
    | Represents CalientS320 using TL1 protocol
    | Kwargs available in the interface:

    :param str model: name of the optical switch model
    :param str addr: IP address or hostname of the device
    :param int, optional timeout: timeout for the request in seconds *(defaults to 5)*
    :param str, optional user_name: username for authentication *(defaults to empty string)*
    :param str, optional password: password for authentication *(defaults to empty string)*
    :param int, optional port: port number of the device *(defaults to 22)*
    :param str, optional protocol: See note at the top of the page
    """

    _LOGIN_USER = "admin"
    _LOGIN_PASSWORD = "pxc***"
    _COMMAND_SUCCESS = "COMPLD"

    def __init__(self, host, port=22, user_name="", password="", timeout=20):
        super().__init__(host=host, port=port, timeout=timeout)
        self._username = user_name
        self._password = password

        self._setup()

    def _setup(self):
        self._session = TL1SSHShellSession(self._host, self._port, self._username, password=self._password)
        self._session.setup()
        self._tl1 = TL1(self._session)
        self._user_login()

    def _user_login(self):
        response = self._tl1.act_user(self._LOGIN_USER, self._LOGIN_PASSWORD, recv_timeout=self._timeout)
        self._check_command_response(response)

    def _user_logout(self):
        response = self._tl1.canc_user()
        self._check_command_response(response)

    def get_optical_switch_channels(self):
        raise NotImplementedError

    def set_optical_switch_channels(self, new_settings):
        raise NotImplementedError

    def set_link_flapping(self, lowperiod, highperiod, period, frequency, repeat, duration, ports):
        """
        This keyword is used to toggle power on ports in disruptive testing.

        :param UNION[str, int] lowperiod: 20ms-30min e.g. 20ms, unit is ms by default when entering *int* value.
        :param UNION[str, int] highperiod: 20ms-30min e.g. 40ms, unit is ms by default when entering *int* value.
        :param UNION[str, int] period: 40ms-1h e.g. 40ms, unit is ms by default when entering *int* value.
        :param UNION[str, float] frequency: 25Hz - 0.00027777Hz.
        :param UNION[str, int] repeat: repeat count, between 1 and 30.
        :param UNION[str, int] duration: 40ms-1h e.g. 40ms, unit is ms by default when entering *int* value.
        :param list[str] ports: standard port list , e.g. ``["4.4.1", "4.4.1", "4.4.3"]``
        :raises OpticalSwitchCommandInvalid: when command response contains error
        """

        ports = self._create_ports_option(ports)
        response = self._tl1.opr_link_flap(
            lowperiod=lowperiod,
            highperiod=highperiod,
            repeat=repeat,
            duration=duration,
            frequency=frequency,
            ports=ports,
            recv_timeout=self._timeout,
        )

        self._check_command_response(response)

    def set_multiple_cross_connections(self, connection_list):
        """
        Set multiple cross connections. Allows the user to make multiple connections on an arbitrary batch of
        connections.

        :param list[str] connection_list: list of connections to be set
            Example: ``["1.1.1-2.2.2", "3.4.1>3.3.3"]``

        :raises OpticalSwitchCommandInvalid: when command response contains error
        """

        response = self._tl1.multiple_cross_connections(connection_list)
        return self._check_command_response(response)

    @staticmethod
    def _create_ports_option(ports):
        if isinstance(ports, list):
            return "&".join(ports)
        return ports

    def _check_command_response(self, response):
        if response.ConditionCode.COMPLD != response.condition_code:
            raise OpticalSwitchCommandInvalid(response.text_block)

    def teardown(self):
        """Teardown and disconnect"""
        self._user_logout()
        self._session.teardown()
